// semantic-evidence-adapter.mjs — resolves a semantic binding's claimed
// evidence (test/semantic/bindings.json's `test_ref`, see semantic-model.mjs
// and cerberus issue #3426) against the identities the executable test
// corpus ALREADY owns: property-test ShapeID rosters (test/property/gen),
// TXTAR spec fixtures (test/spec/**), the surface-parity inventory
// (test/surface-parity/inventory/), the rejection-parity catalogue
// (test/rejection-parity/catalogue/), the QL feature inventory
// (test/e2e/grafana/ql-inventory/, generated by test/oracle/inventory)
// (cerberus issue #3428), and — for every binding whose evidence is a plain
// Go test, a harness directory, a gate script or a config file — the
// source tree itself.
//
// WHY THIS EXISTS. Each of those systems already independently declares
// its own stable identities. Without a join, a semantic binding's test_ref
// is just a string nobody checks — a fixture can be deleted, a ShapeID
// renamed, a rejection site's guard can move, a Go test function can be
// renamed away, and the binding goes on claiming evidence for a contract
// that no longer has any. This module is that join: it resolves a test_ref
// to the identity it names in whichever system owns it, and reports — by
// name, not by a generic failure — when it does not. Every binding is
// resolved: a test_ref that fits none of the six schemes below is itself a
// dangling reference, never "not applicable".
//
// WHAT THIS MODULE NEVER DOES. It never copies a system's rows or expected
// answers into the semantic layer — every resolver returns a reference (an
// identity that was found, or a problem naming what's missing), never the
// underlying data. It never writes to any of the six systems or to
// test/semantic/*.json: every exported function here only reads. See
// semantic-evidence-adapter.test.mjs's "adapter never writes" meta-test,
// which greps this file's own source for write APIs and asserts none exist.
//
// TEST_REF ADDRESSING SCHEME. `binding.test_ref` is a plain string in the
// #3426 schema (no format the loader enforces beyond "non-empty"), so this
// module defines the scheme for the six systems below. The five ledger
// schemes are tried first (they own their prefixes); anything else that is
// a well-formed repo-relative path, optionally suffixed with `:GoTestName`
// or `#token`, is a source-path reference.
//
//   property-shape          test/property/gen#<shapeID>
//   txtar-fixture            test/spec/<head>/<name>.txtar[#<section>]
//                             (an existing example: the #3426 binding
//                             BINDING-PROMQL-RANGE-ALIGNMENT-SPEC already
//                             uses the bare repo-relative fixture path with
//                             no fragment; the fragment form is new here,
//                             for a binding that claims evidence from one
//                             specific TXTAR section — most usefully
//                             `#sql_optimized` / `#args_optimized`, the
//                             "current optimized TXTAR sections" issue
//                             #3428's own scope names (see
//                             docs/test-strategy.md's Layer 2a guidance and
//                             test/spec/runner_chdb.go's optimized-plan
//                             round trip): a binding scoped to `#sql` alone
//                             is evidence about the PRE-optimizer lowering,
//                             while one scoped to `#sql_optimized` is
//                             evidence about the plan the optimizer produced
//                             and chDB actually executed — two different
//                             claims about the same fixture file.)
//   surface-parity-symbol    test/surface-parity#<head>/<symbol>
//   rejection-parity-site    <the catalogue Site key verbatim>, e.g.
//                             internal/promql/lower.go:lowerFoo#a1b2c3d4
//   oracle-inventory-case     test/oracle/inventory#<ql>/<id>
//   source-path               <repo-relative path>[:<GoTestName>|#<token>]
//                             A file must exist. With `:TestName` the file
//                             must declare `func TestName(`. With `#token`
//                             (a named scenario inside a script, e.g.
//                             `.github/scripts/chaos-run.mjs#ch-pod-kill`)
//                             the file must contain the token literally. A
//                             bare directory (a package or a harness root
//                             such as `internal/engine` or
//                             `compatibility/prometheus`) must exist and
//                             hold at least one `.go` file somewhere below
//                             it — an empty or Go-less directory is not a
//                             test anyone can run.
//
// GO EXPORT HELPER. Four of the five ledger systems above already have a
// Node-readable serialized form on disk (TXTAR fixtures are plain text;
// the surface-parity, rejection-parity and oracle-inventory ledgers are
// checked-in JSON). Only the property-test ShapeID rosters are Go
// compile-time values with no serialized form — see
// test/semantic/cmd/property-shape-export's own header comment for why that
// is the one case genuinely requiring a Go export helper, per issue #3428's
// own scope. loadPropertyShapeExport shells out to it (go run, no build
// tag) rather than caching its output in a checked-in file: the export is a
// pure, deterministic function of test/property/gen's current source, so
// running it live carries zero staleness risk and needs no regeneration
// recipe — the "second, manually-synchronized corpus" problem this whole
// module exists to avoid cannot arise for data that is never actually
// copied anywhere.

import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

export class SemanticEvidenceAdapterError extends Error {
  constructor(problems) {
    super(`semantic evidence adapter:\n${problems.map((p) => `- ${p}`).join("\n")}`);
    this.name = "SemanticEvidenceAdapterError";
    this.problems = problems;
  }
}

// --- TXTAR parsing --------------------------------------------------------
//
// Reimplements golang.org/x/tools/txtar's Parse format in Node builtins:
// content before the first marker line is discarded (spec fixtures carry
// none), and each `-- name --` line (surrounding whitespace on the name
// trimmed, per the upstream format) starts a new named section running to
// the next marker or end of file. This is SOURCE PARSING of a fixed,
// documented text format — not a heuristic over Go source — the same
// distinction issue #3428's own non-goals draw around "regex-guessing of Go
// execution".
const TXTAR_MARKER_RE = /^-- (.*) --$/;

/** Parses raw TXTAR bytes into an ordered array of {name, content}. */
export function parseTxtar(text) {
  // Split AFTER each newline (keeping the terminator attached to the line
  // it ends) so a section's content is reassembled byte-for-byte, including
  // whether its final line carries a trailing newline — naively splitting
  // on "\n" and rejoining with "\n" per line invents a newline the source
  // file may not have had.
  const lines = text.split(/(?<=\n)/);
  const sections = [];
  let current = null;
  for (const rawLine of lines) {
    const line = rawLine.endsWith("\n") ? rawLine.slice(0, -1) : rawLine;
    const m = TXTAR_MARKER_RE.exec(line);
    if (m) {
      current = { name: m[1].trim(), content: "" };
      sections.push(current);
      continue;
    }
    if (current) current.content += rawLine;
  }
  return sections;
}

/** Loads and parses one TXTAR fixture. `relPath` is repo-root-relative. */
export function loadTxtarFixture(repoRoot, relPath) {
  const abs = join(repoRoot, relPath);
  const text = readFileSync(abs, "utf8");
  return { path: relPath, sections: parseTxtar(text) };
}

// --- Property-shape export loader -----------------------------------------

const PROPERTY_SHAPE_EXPORT_PKG = "./test/semantic/cmd/property-shape-export";

function defaultRunExporter(repoRoot) {
  const result = spawnSync("go", ["run", PROPERTY_SHAPE_EXPORT_PKG], {
    cwd: repoRoot,
    encoding: "utf8",
    maxBuffer: 16 * 1024 * 1024,
  });
  if (result.status !== 0) {
    throw new SemanticEvidenceAdapterError([
      `[export] property-shape-export exited ${result.status}: ${result.stderr || result.error}`,
    ]);
  }
  return JSON.parse(result.stdout);
}

/**
 * Runs (or, under `runExporter`, simulates) the property-shape-export Go
 * helper and returns its parsed JSON: `{ schema_version, rosters }`, where
 * `rosters` maps a roster call name (e.g. "gen.PromQLShapeIDs") to its
 * exact, ordered ShapeID roster. `runExporter` is injectable so unit tests
 * can exercise dangling-reference detection without a `go` toolchain; the
 * CLI and at least one test always use the real default.
 */
export function loadPropertyShapeExport({ repoRoot = process.cwd(), runExporter = defaultRunExporter } = {}) {
  const doc = runExporter(repoRoot);
  if (!doc || typeof doc !== "object" || !doc.rosters || typeof doc.rosters !== "object") {
    throw new SemanticEvidenceAdapterError([
      "[export] property-shape-export produced no rosters object",
    ]);
  }
  return doc;
}

// --- Sharded JSON ledger loaders ------------------------------------------

function readShardedEntries(dir) {
  let names;
  try {
    names = readdirSync(dir).filter((n) => n.endsWith(".json"));
  } catch {
    return [];
  }
  const entries = [];
  for (const name of names.sort()) {
    const doc = JSON.parse(readFileSync(join(dir, name), "utf8"));
    if (Array.isArray(doc.entries)) entries.push(...doc.entries);
  }
  return entries;
}

/** Merges every shard under test/surface-parity/inventory/ into one array. */
export function loadSurfaceParityInventory(repoRoot) {
  return readShardedEntries(join(repoRoot, "test/surface-parity/inventory"));
}

/** Merges every shard under test/rejection-parity/catalogue/ into one array. */
export function loadRejectionParityCatalogue(repoRoot) {
  return readShardedEntries(join(repoRoot, "test/rejection-parity/catalogue"));
}

/** Loads the three per-QL feature inventories test/oracle/inventory generates. */
export function loadOracleInventory(repoRoot) {
  const out = {};
  for (const ql of ["promql", "logql", "traceql"]) {
    const path = join(repoRoot, `test/e2e/grafana/ql-inventory/${ql}-feature-inventory.json`);
    const doc = JSON.parse(readFileSync(path, "utf8"));
    out[ql] = Array.isArray(doc.rows) ? doc.rows : [];
  }
  return out;
}

/** Reads the parity-enrolment baseline roster for one head (see test/regression/parity_enrolment_test.go). */
export function loadParityEnrolmentBaseline(repoRoot, head) {
  const path = join(repoRoot, `test/regression/parity-enrolment-baselines/${head}/baseline.txt`);
  const text = readFileSync(path, "utf8");
  return text.split("\n").filter(Boolean);
}

// --- test_ref classification -----------------------------------------------

export const EVIDENCE_SYSTEMS = Object.freeze([
  "property-shape",
  "txtar-fixture",
  "surface-parity-symbol",
  "rejection-parity-site",
  "oracle-inventory-case",
  "source-path",
]);

const PROPERTY_SHAPE_PREFIX = "test/property/gen#";
const SURFACE_PARITY_PREFIX = "test/surface-parity#";
const ORACLE_INVENTORY_PREFIX = "test/oracle/inventory#";

// Mirrors test/rejection-parity/catalogue.go's own site-key shape exactly:
// "<file>.go:<func>#<hash8>" with an optional "-<n>" repeat ordinal.
const REJECTION_SITE_RE =
  /^internal\/(promql|logql|traceql)\/[^:]+\.go:[A-Za-z0-9_]+#[0-9a-f]{8}(-\d+)?$/;

// A source-path reference: a repo-relative path (no leading slash, no `..`
// segment, the character set git itself uses for tracked paths here), then
// at most ONE of `:GoIdentifier` (a test function) or `#token` (a literal
// scenario name inside the file). Both at once is not a shape any resolver
// could check, so it is left unclassified — and unclassified is dangling.
const SOURCE_PATH_RE =
  /^(?<path>(?!\/)(?!.*(?:^|\/)\.\.(?:\/|$))[A-Za-z0-9_.\/-]+)(?:(?::(?<symbol>[A-Za-z_][A-Za-z0-9_]*))|(?:#(?<token>[^#:\s]+)))?$/;

/**
 * Classifies a binding's test_ref into one of the six systems this module
 * resolves, or `{ system: null }` when no scheme can parse it. The five
 * ledger schemes own their prefixes and are tried first; source-path is
 * the fallback for any well-formed repo-relative path.
 */
export function classifyTestRef(testRef) {
  if (typeof testRef !== "string" || testRef.length === 0) {
    return { system: null };
  }
  if (REJECTION_SITE_RE.test(testRef)) {
    return { system: "rejection-parity-site", site: testRef };
  }
  if (testRef.startsWith(PROPERTY_SHAPE_PREFIX)) {
    return { system: "property-shape", shapeID: testRef.slice(PROPERTY_SHAPE_PREFIX.length) };
  }
  if (testRef.startsWith(SURFACE_PARITY_PREFIX)) {
    const [head, symbol] = splitOnce(testRef.slice(SURFACE_PARITY_PREFIX.length), "/");
    return { system: "surface-parity-symbol", head, symbol };
  }
  if (testRef.startsWith(ORACLE_INVENTORY_PREFIX)) {
    const [ql, id] = splitOnce(testRef.slice(ORACLE_INVENTORY_PREFIX.length), "/");
    return { system: "oracle-inventory-case", ql, id };
  }
  if (testRef.startsWith("test/spec/")) {
    const [path, fragment] = splitOnce(testRef, "#");
    if (path.endsWith(".txtar")) {
      return { system: "txtar-fixture", path, section: fragment ?? null };
    }
  }
  const source = SOURCE_PATH_RE.exec(testRef);
  if (source) {
    return {
      system: "source-path",
      path: source.groups.path,
      symbol: source.groups.symbol ?? null,
      token: source.groups.token ?? null,
    };
  }
  return { system: null };
}

function splitOnce(s, sep) {
  const i = s.indexOf(sep);
  if (i < 0) return [s, undefined];
  return [s.slice(0, i), s.slice(i + sep.length)];
}

// --- Per-system resolvers ---------------------------------------------------
//
// Every resolver returns { ok, detail, problems }. `problems` is a non-empty
// array of human-readable strings naming exactly what is missing and where
// — never a generic "not found" — per issue #3428's own acceptance
// criterion that a removed/renamed identity produces a USEFUL error.

function ok(detail) {
  return { ok: true, detail, problems: [] };
}

function fail(problems) {
  return { ok: false, detail: null, problems };
}

/** Resolves a `property-shape` test_ref against a loaded shape export. */
export function resolvePropertyShapeEvidence(testRef, shapeExport) {
  const { shapeID } = classifyTestRef(testRef);
  if (!shapeID) {
    return fail([`test_ref ${JSON.stringify(testRef)} carries no shape ID after "${PROPERTY_SHAPE_PREFIX}"`]);
  }
  for (const [rosterCall, ids] of Object.entries(shapeExport.rosters)) {
    if (ids.includes(shapeID)) return ok({ rosterCall, shapeID });
  }
  return fail([
    `test_ref ${JSON.stringify(testRef)} names shape ID ${JSON.stringify(shapeID)}, which does not ` +
      "exist in any gen.*ShapeIDs() roster (test/property/gen/shapes.go) — it was removed or renamed",
  ]);
}

/**
 * Resolves a `txtar-fixture` test_ref: the fixture file must exist under
 * `repoRoot`, and — when the test_ref carries a `#section` fragment — that
 * section must be present in it. This is what lets a binding scoped to
 * `#sql_optimized` fail loudly when it points at a fixture that has never
 * carried the optimized pair (e.g. one that opts out of the chDB round trip).
 */
export function resolveTxtarEvidence(testRef, repoRoot) {
  const { path, section } = classifyTestRef(testRef);
  if (!path) return fail([`test_ref ${JSON.stringify(testRef)} is not a test/spec/**/*.txtar reference`]);
  const abs = join(repoRoot, path);
  if (!existsSync(abs)) {
    return fail([`TXTAR fixture ${path} referenced by test_ref ${JSON.stringify(testRef)} does not exist`]);
  }
  const { sections } = loadTxtarFixture(repoRoot, path);
  if (section) {
    const found = sections.find((s) => s.name === section);
    if (!found) {
      const have = sections.map((s) => s.name).join(", ") || "(none)";
      return fail([
        `TXTAR fixture ${path} has no "-- ${section} --" section (test_ref ${JSON.stringify(testRef)}); ` +
          `sections present: ${have}`,
      ]);
    }
  }
  return ok({ path, section: section ?? null, sections: sections.map((s) => s.name) });
}

/** Resolves a `surface-parity-symbol` test_ref against the merged inventory. */
export function resolveSurfaceParityEvidence(testRef, inventoryEntries) {
  const { head, symbol } = classifyTestRef(testRef);
  if (!head || !symbol) {
    return fail([`test_ref ${JSON.stringify(testRef)} is not a "${SURFACE_PARITY_PREFIX}<head>/<symbol>" reference`]);
  }
  const entry = inventoryEntries.find((e) => e.head === head && e.symbol === symbol);
  if (!entry) {
    return fail([
      `surface-parity inventory has no entry for head=${head} symbol=${JSON.stringify(symbol)} ` +
        `(test_ref ${JSON.stringify(testRef)}) — it was removed, renamed, or never generated`,
    ]);
  }
  return ok(entry);
}

/** Resolves a `rejection-parity-site` test_ref against the merged catalogue. */
export function resolveRejectionParityEvidence(testRef, catalogueEntries) {
  const { site } = classifyTestRef(testRef);
  if (!site) return fail([`test_ref ${JSON.stringify(testRef)} is not a rejection-parity site key`]);
  const entry = catalogueEntries.find((e) => e.site === site);
  if (!entry) {
    return fail([
      `rejection-parity catalogue has no site ${JSON.stringify(site)} — the error-construction site ` +
        "it named was removed, moved, or its message changed (site keys hash the message)",
    ]);
  }
  return ok(entry);
}

/** Resolves an `oracle-inventory-case` test_ref against the QL feature inventory. */
export function resolveOracleInventoryEvidence(testRef, oracleInventory) {
  const { ql, id } = classifyTestRef(testRef);
  if (!ql || !id) {
    return fail([`test_ref ${JSON.stringify(testRef)} is not a "${ORACLE_INVENTORY_PREFIX}<ql>/<id>" reference`]);
  }
  const rows = oracleInventory[ql];
  if (!rows) {
    return fail([`test_ref ${JSON.stringify(testRef)} names unknown QL ${JSON.stringify(ql)}`]);
  }
  const row = rows.find((r) => r.id === id);
  if (!row) {
    return fail([
      `${ql} feature inventory (test/e2e/grafana/ql-inventory/${ql}-feature-inventory.json) has no row ` +
        `${JSON.stringify(id)} (test_ref ${JSON.stringify(testRef)}) — it was removed or renamed`,
    ]);
  }
  return ok(row);
}

function hasGoFileBelow(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isFile() && entry.name.endsWith(".go")) return true;
    if (entry.isDirectory() && hasGoFileBelow(join(dir, entry.name))) return true;
  }
  return false;
}

/**
 * Resolves a `source-path` test_ref against the checkout at `repoRoot`:
 * the path must exist; a `:TestName` suffix requires a FILE declaring
 * `func TestName(`; a `#token` suffix requires the file to contain the
 * token literally; a bare directory must hold at least one `.go` file
 * somewhere below it.
 */
export function resolveSourcePathEvidence(testRef, repoRoot) {
  const { system, path, symbol, token } = classifyTestRef(testRef);
  if (system !== "source-path") {
    return fail([`test_ref ${JSON.stringify(testRef)} is not a source-path reference`]);
  }
  const abs = join(repoRoot, path);
  let stat;
  try {
    stat = statSync(abs);
  } catch (err) {
    if (err?.code === "ENOENT" || err?.code === "ENOTDIR") {
      return fail([`${path} referenced by test_ref ${JSON.stringify(testRef)} does not exist on disk`]);
    }
    throw err;
  }
  if (stat.isDirectory()) {
    if (symbol !== null || token !== null) {
      return fail([
        `${path} (test_ref ${JSON.stringify(testRef)}) is a directory, so a :${symbol ?? ""}${token !== null ? `#${token}` : ""} suffix names nothing inside it`,
      ]);
    }
    if (!hasGoFileBelow(abs)) {
      return fail([
        `${path} (test_ref ${JSON.stringify(testRef)}) is a directory with no .go file anywhere below it — not a package or harness anyone can run`,
      ]);
    }
    return ok({ path, kind: "directory", symbol: null, token: null });
  }
  const text = readFileSync(abs, "utf8");
  if (symbol !== null && !text.includes(`func ${symbol}(`)) {
    return fail([
      `${path} does not declare \`func ${symbol}(\` (test_ref ${JSON.stringify(testRef)}) — the test was removed or renamed`,
    ]);
  }
  if (token !== null && !text.includes(token)) {
    return fail([
      `${path} does not contain ${JSON.stringify(token)} (test_ref ${JSON.stringify(testRef)}) — the named scenario was removed or renamed`,
    ]);
  }
  return ok({ path, kind: "file", symbol, token });
}

/**
 * Resolves any binding's test_ref against whichever of the six systems
 * `indices` provides pre-loaded data for. Returns
 * `{ system, ok, detail, problems }`; `system: null` means no scheme could
 * parse the test_ref, which is reported as a dangling reference — a
 * binding's evidence claim is either checkable or it is not a claim.
 */
export function resolveBindingEvidence(binding, indices) {
  const classified = classifyTestRef(binding.test_ref);
  switch (classified.system) {
    case "property-shape": {
      const r = resolvePropertyShapeEvidence(binding.test_ref, indices.shapeExport);
      return { system: classified.system, ...r };
    }
    case "txtar-fixture": {
      const r = resolveTxtarEvidence(binding.test_ref, indices.repoRoot);
      return { system: classified.system, ...r };
    }
    case "surface-parity-symbol": {
      const r = resolveSurfaceParityEvidence(binding.test_ref, indices.surfaceParityEntries);
      return { system: classified.system, ...r };
    }
    case "rejection-parity-site": {
      const r = resolveRejectionParityEvidence(binding.test_ref, indices.rejectionCatalogueEntries);
      return { system: classified.system, ...r };
    }
    case "oracle-inventory-case": {
      const r = resolveOracleInventoryEvidence(binding.test_ref, indices.oracleInventory);
      return { system: classified.system, ...r };
    }
    case "source-path": {
      const r = resolveSourcePathEvidence(binding.test_ref, indices.repoRoot);
      return { system: classified.system, ...r };
    }
    default:
      return {
        system: null,
        ok: false,
        detail: null,
        problems: [
          `test_ref ${JSON.stringify(binding.test_ref)} matches none of the six evidence schemes ` +
            `(${EVIDENCE_SYSTEMS.join(", ")}) — nothing can check whether it still names a real test`,
        ],
      };
  }
}

/**
 * Runs resolveBindingEvidence over every binding in a loaded semantic model
 * (loadSemanticModel()'s return value — see lib/semantic-model.mjs) and
 * returns the problems for every binding whose test_ref fails to resolve,
 * including one no scheme can parse. No binding is skipped.
 */
export function diagnoseDanglingBindings(model, indices) {
  const problems = [];
  for (const [, binding] of model.bindings) {
    const result = resolveBindingEvidence(binding, indices);
    if (result.ok) continue;
    for (const p of result.problems) {
      problems.push(`${binding.at} (${binding.id}, contract ${binding.contract}): ${p}`);
    }
  }
  return problems;
}

// --- Declaration vs. execution ---------------------------------------------
//
// Mirrors (rather than imports, since issue #3428 is independent of #3427's
// PR) the classifyObservedEvidence concept: only a real pass/fail verdict
// counts as OBSERVED evidence a binding's verifier actually ran, consistent
// with #3426's own execution.result vocabulary (pass/fail/error) — "error"
// means the run itself broke, not that it exercised the contract, so it
// never counts as observed evidence either.
const OBSERVED_EXECUTION_RESULTS = new Set(["pass", "fail"]);

export function classifyObservedEvidence(execution) {
  if (!execution || typeof execution.result !== "string") {
    return { observed: false, reason: "missing or malformed execution record" };
  }
  if (!OBSERVED_EXECUTION_RESULTS.has(execution.result)) {
    return {
      observed: false,
      reason: `result ${JSON.stringify(execution.result)} is not a real verdict (error/missing never count as evidence)`,
    };
  }
  return { observed: true, reason: null };
}

// --- Property-shape roster family discovery ---------------------------------
//
// Independent of test/regression/property_live_roster_floor_test.go's own
// go/ast-based discovery: this scans the SAME test/property/*_test.go
// source with a Node-side scan of its own, landing on the same families by
// re-deriving them from current source rather than by importing or copying
// the Go test's pinned table. A family that loses its roster wiring, its
// randomized runner, or its file entirely is reported as a problem rather
// than silently vanishing from the returned array's count.

const PROPERTY_TEST_FILE_SUFFIX = "_test.go";
const PROPERTY_TEST_PACKAGE = "property_test";
const PACKAGE_LINE_RE = /^package\s+(\S+)\s*$/m;
// Matches `property.RunShapeExamples(\n\tt,\n\tgen.PromQLShapeIDs(),` and the
// RunShapeCases sibling — the exact two-argument opening every live-roster
// property test in this repo uses (see test/property/promql_test.go etc.).
// RunShapeExamplesWithComparator (issue #3443) is the same opening with a
// third, comparator-callback argument — test/property/traceql_test.go's own
// roster call — so it must match here too or the family silently vanishes
// from discovery.
const LIVE_ROSTER_CALL_RE =
  /property\.(RunShapeExamples(?:WithComparator)?|RunShapeCases)\(\s*t,\s*(gen\.\w+)\(\)/;
// Any of the three randomized-search entry points this repo's property
// tests use (test/regression/property_live_roster_floor_test.go's own
// propertyRandomRunnerFloor pins the same three call names).
const RANDOM_RUNNER_CALL_RE = /property\.Run\(t,|property\.RunLogs\(t,|rapid\.Check\(t,/;

/**
 * Discovers the property-test roster families under `propertyDir`
 * (default test/property): one entry per `package property_test` file that
 * wires a live-roster runner (RunShapeExamples/RunShapeCases) to a
 * `gen.*ShapeIDs()` roster call. Cross-references each discovered roster
 * call against the real `property-shape-export` output (never a hardcoded
 * expectation), and flags a family whose file carries a live-roster call
 * with no randomized-runner call alongside it.
 */
export function discoverPropertyRosterFamilies({
  repoRoot = process.cwd(),
  propertyDir = "test/property",
  runExporter,
} = {}) {
  const dir = join(repoRoot, propertyDir);
  const shapeExport = loadPropertyShapeExport({ repoRoot, runExporter });
  const files = readdirSync(dir).filter((f) => f.endsWith(PROPERTY_TEST_FILE_SUFFIX));

  const families = [];
  for (const file of files.sort()) {
    const text = readFileSync(join(dir, file), "utf8");
    const pkg = PACKAGE_LINE_RE.exec(text);
    if (!pkg || pkg[1] !== PROPERTY_TEST_PACKAGE) continue;
    const rosterMatch = LIVE_ROSTER_CALL_RE.exec(text);
    if (!rosterMatch) continue;

    const rosterCall = rosterMatch[2];
    const family = file.slice(0, -PROPERTY_TEST_FILE_SUFFIX.length);
    const hasRandomRunner = RANDOM_RUNNER_CALL_RE.test(text);
    const shapeIDs = shapeExport.rosters[rosterCall];
    const problems = [];
    if (!shapeIDs) {
      problems.push(
        `${propertyDir}/${file} wires live-roster call "${rosterCall}" but property-shape-export ` +
          "reports no such roster — it was renamed or removed from test/property/gen",
      );
    }
    if (!hasRandomRunner) {
      problems.push(
        `${propertyDir}/${file} has a live-roster binding but no randomized-runner call ` +
          "(property.Run / property.RunLogs / rapid.Check)",
      );
    }
    families.push({
      family,
      file: `${propertyDir}/${file}`,
      rosterCall,
      shapeIDs: shapeIDs ?? [],
      hasLiveRoster: true,
      hasRandomRunner,
      problems,
    });
  }
  return families;
}
